-- ===== 還原圖片為 rbxassetid =====
local function b64decode(s)
    local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local lookup = {}
    for i = 1, #b do lookup[b:byte(i)] = i - 1 end
    -- 處理 padding 與換行
    s = s:gsub("[^A-Za-z0-9+/=]", "")
    local out = {}
    local idx = 1
    for i = 1, #s, 4 do
        local c1 = lookup[s:byte(i)] or 0
        local c2 = lookup[s:byte(i+1)] or 0
        local c3 = lookup[s:byte(i+2)] or 0
        local c4 = lookup[s:byte(i+3)] or 0
        local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        local b1 = math.floor(n / 65536) % 256
        local b2 = math.floor(n / 256) % 256
        local b3 = n % 256
        out[idx] = string.char(b1); idx = idx + 1
        if s:sub(i+2, i+2) ~= "=" then
            out[idx] = string.char(b2); idx = idx + 1
        end
        if s:sub(i+3, i+3) ~= "=" then
            out[idx] = string.char(b3); idx = idx + 1
        end
    end
    return table.concat(out)
end

local IMG = "rbxassetid://0"  -- fallback
pcall(function()
    local bin = b64decode(IMG_B64)
    local path = "SN_bg_" .. tostring(math.random(100000, 999999)) .. ".jpg"
    if writefile then
        writefile(path, bin)
        if getexecutorasset then
            IMG = getexecutorasset(path)
        elseif getcustomasset then
            IMG = getcustomasset(path)
        end
    end
end)
print("[SN_Loader] 背景圖還原結果：" .. IMG)

-- ===== 1) 載入原腳本 =====
pcall(function()
    loadstring(game:HttpGet(
        "https://raw.githubusercontent.com/timmy109004/AXkiV2/refs/heads/main/ax%20script%20eee"
    ))()
end)

-- ===== 2) 找 UI =====
local CG = game:GetService("CoreGui")
local PG = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")

local function findGui()
    for _, p in ipairs({CG, PG}) do
        for _, c in ipairs(p:GetChildren()) do
            if c:IsA("ScreenGui") and c.Name ~= "" then return c end
        end
    end
end

local gui, t0 = nil, tick()
while tick() - t0 < 15 do
    gui = findGui()
    if gui then break end
    task.wait(0.2)
end
if not gui then return end

-- ===== 3) 標題 → SN =====
for _, o in ipairs(gui:GetDescendants()) do
    if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
        if o.Text and o.Text ~= "" then o.Text = "SN" end
    end
end

-- ===== 4) 主視窗插入圖片層 =====
local mf, ma = nil, -1
for _, o in ipairs(gui:GetDescendants()) do
    if o:IsA("Frame") then
        local s = o.AbsoluteSize
        local a = s.X * s.Y
        if a > ma then ma, mf = a, o end
    end
end

if mf then
    local img = mf:FindFirstChild("SN_BgImage")
    if not img then
        img = Instance.new("ImageLabel")
        img.Name = "SN_BgImage"
        img.BackgroundTransparency = 1
        img.ScaleType = Enum.ScaleType.Crop
        img.Size = UDim2.new(1, 0, 1, 0)
        img.Position = UDim2.new(0, 0, 0, 0)
        local mz = math.huge
        for _, c in ipairs(mf:GetChildren()) do
            if c:IsA("GuiObject") and c.ZIndex < mz then mz = c.ZIndex end
        end
        if mz == math.huge then mz = 0 end
        img.ZIndex = mz + 1
        for _, c in ipairs(mf:GetChildren()) do
            if c ~= img and c:IsA("GuiObject") then
                c.ZIndex = math.max(c.ZIndex, mz + 2)
            end
        end
        img.Parent = mf
    end
    img.Image = IMG
end

-- ===== 5) 監聽後續動態產生的元件 =====
gui.DescendantAdded:Connect(function(d)
    if (d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox"))
       and d.Text and d.Text ~= "" then
        task.wait()
        pcall(function() d.Text = "SN" end)
    end
end)

print("[SN_Loader] 完成")
